// Package assets embeds the built renderer bundle so the server ships as a
// single binary. The bundle is generated by `cd renderer && npm run build`
// (configured in renderer/vite.config.ts to emit into ../server/assets/dist).
//
// During plain `go build` without a prior renderer build, the dist directory
// must still exist (even if empty) for the embed directive to succeed; the
// repository ships a placeholder index.html committed under server/assets/dist
// to keep the embed valid in fresh clones.
package assets

import "embed"

// Dist is the embedded renderer bundle, served by the HTTP layer at /static/.
//
//go:embed all:dist
var Dist embed.FS
